iewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Clifton School at Summerfield has been proposed as a historical model for Deasy’s school; the identification is an inference.","it":"La Clifton School di Summerfield è stata proposta come modello storico della scuola di Deasy; l’identificazione resta un’ipotesi.","fr":"La Clifton School de Summerfield a été proposée comme modèle historique de l’école de Deasy ; l’identification reste hypothétique.","es":"La Clifton School de Summerfield se ha propuesto como modelo histórico de la escuela de Deasy; la identificación sigue siendo hipotética."}}},{"book":"ulisse","id":"station","collection":"core","name":"Westland Row Station","noteHash":"474752b2764247197e4135623cc1a125","positionSource":"d95216c86088b1b0a1fb76517520538b3798b95480cad46f649495ddf13921da","narrativeSource":"c7db9059a97482854ddf125bb5671be6e39ae214f4356b3b67c9999948a860bf","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Westland Row Station is associated with the railway journey towards Amiens Street.","it":"La Westland Row Station è associata al viaggio ferroviario verso Amiens Street.","fr":"Westland Row Station est associée au trajet ferroviaire vers Amiens Street.","es":"Westland Row Station está asociada al viaje ferroviario hacia Amiens Street."}}},{"book":"ulisse","id":"strand","collection":"core","name":"The Proteus shore","noteHash":"fa0ab216c1e5dbab420222955dd34fd2","positionSource":"725a97f6f2f76aa41a194da9567ac553f892c8f40114a5ba03b310b3ed11967c","narrativeSource":"7c698b2f50fb0daa370ab2a154f20ce80939e7d105f9ba07ddae0621ef0f2137","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Stephen walks along the northern shore in Proteus; land reclamation has since changed the coastline.","it":"Stephen cammina lungo la riva settentrionale nel Proteo; le bonifiche hanno poi modificato la costa.","fr":"Stephen marche le long de la rive nord dans Protée ; les remblais ont depuis modifié le littoral.","es":"Stephen camina por la orilla norte en Proteo; los rellenos han cambiado desde entonces la costa."}}},{"book":"ulisse","id":"viceregal","collection":"core","name":"Viceregal Lodge","noteHash":"d0ba1929d908e71a1b03f4670d047c88","positionSource":"725a97f6f2f76aa41a194da9567ac553f892c8f40114a5ba03b310b3ed11967c","narrativeSource":"ea31350b7c6af2f19e4548516e011c977f362524b7acbd7e22e1deed806c6a52","description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"The viceregal procession sets out from the Viceregal Lodge complex.","it":"Il corteo vicereale parte dal complesso della Viceregal Lodge.","fr":"Le cortège vice-royal part du domaine de la Viceregal Lodge.","es":"El cortejo virreinal parte del complejo de la Viceregal Lodge."}}}]'::jsonb; expected integer := 16;
begin
 if (select count(*) from public.place_descriptions d join jsonb_to_recordset(p) x(book text,id text,collection text,"noteHash" text,"positionSource" text,"narrativeSource" text,description jsonb) on d.book_id=x.book and d.place_id=x.id and d.collection=x.collection where md5(coalesce(d.note,''))=x."noteHash" and d.position_source_id::text=x."positionSource" and d.narrative_source_id::text is not distinct from x."narrativeSource" and (not (coalesce(d.metadata,'{}'::jsonb) ? 'positionDescription') or d.metadata->'positionDescription'=x.description)) <> expected then raise exception 'A source or summary changed; no updates applied'; end if;
 update public.place_descriptions d set metadata=jsonb_set(coalesce(d.metadata,'{}'::jsonb),'{positionDescription}',x.description,true) from jsonb_to_recordset(p) x(book text,id text,collection text,description jsonb) where d.book_id=x.book and d.place_id=x.id and d.collection=x.collection;
end $revision$;
